import csv, io, json, os, sys
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read(d, name):
    p = os.path.join(d, name)
    if not os.path.exists(p):
        return []
    with open(p, encoding="utf-8-sig", newline="") as f:
        rows = []
        rd = csv.reader(f)
        hdr = None
        for r in rd:
            if not any(c.strip() for c in r):
                continue
            if hdr is None:
                hdr = [c.strip() for c in r]
                continue
            r = [c.strip() for c in r]
            rows.append({h: (r[i] if i < len(r) else "") for i, h in enumerate(hdr)})
        return rows


def ftime(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def main(inp, outp):
    with open(os.path.join(inp, "request.json"), encoding="utf-8-sig") as f:
        req = json.load(f)
    dates = sorted(set(req["service_dates"]))
    agencies = read(inp, "agency.txt")
    atz = {a["agency_id"]: a["agency_timezone"] for a in agencies}
    first_tz = agencies[0]["agency_timezone"]
    first_aid = agencies[0]["agency_id"]
    stops = {s["stop_id"]: s for s in read(inp, "stops.txt")}
    routes = {r["route_id"]: r for r in read(inp, "routes.txt")}
    trips = {t["trip_id"]: t for t in read(inp, "trips.txt")}
    cal = {c["service_id"]: c for c in read(inp, "calendar.txt")}
    exc = {}
    for e in read(inp, "calendar_dates.txt"):
        exc[(e["service_id"], e["date"])] = e["exception_type"]
    freqs = {}
    for fr in read(inp, "frequencies.txt"):
        freqs.setdefault(fr["trip_id"], []).append(fr)
    st = {}
    for r in read(inp, "stop_times.txt"):
        st.setdefault(r["trip_id"], []).append(r)

    def runs(sid, d):
        ds = d.strftime("%Y%m%d")
        e = exc.get((sid, ds))
        if e == "1":
            return True
        if e == "2":
            return False
        c = cal.get(sid)
        if not c:
            return False
        if not (c["start_date"] <= ds <= c["end_date"]):
            return False
        wd = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"][d.weekday()]
        return c[wd] == "1"

    def board_of(sid):
        s = stops[sid]
        p = s.get("parent_station", "")
        return p if p and p in stops else sid

    board_stops = {}
    for sid, s in stops.items():
        lt = s.get("location_type", "")
        if lt == "1" or (lt in ("", "0") and not s.get("parent_station", "")):
            board_stops[sid] = s

    def btz(sid):
        return board_stops[sid].get("stop_timezone", "") or first_tz

    # precompute trip patterns
    pat = {}
    for tid, rows in st.items():
        if tid not in trips:
            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        times = []
        for r in rows:
            t = r.get("departure_time") or r.get("arrival_time")
            times.append(ftime(t) if t else None)
        n = len(rows)
        i = 0
        while i < n:
            if times[i] is None:
                a = i - 1
                b = i
                while times[b] is None:
                    b += 1
                for k in range(i, b):
                    times[k] = times[a] + (times[b] - times[a]) * (k - a) // (b - a)
                i = b
            i += 1
        pat[tid] = (rows, times)

    out_boards = {}
    for bid in board_stops:
        for ds in dates:
            out_boards[(bid, ds)] = []

    for ds in dates:
        d = date.fromisoformat(ds)
        for tid, t in trips.items():
            if tid not in pat or not runs(t["service_id"], d):
                continue
            rows, times = pat[tid]
            route = routes[t["route_id"]]
            aid = route.get("agency_id", "") or first_aid
            tz = ZoneInfo(atz.get(aid, first_tz))
            noon = datetime(d.year, d.month, d.day, 12, tzinfo=tz)
            origin = noon.timestamp() - 43200
            label = route.get("route_short_name", "") or route.get("route_long_name", "")
            last = rows[-1]
            ls = stops[last["stop_id"]]
            lb = stops[board_of(last["stop_id"])]
            lastname = lb["stop_name"]
            deps = []
            for k, r in enumerate(rows):
                if k == len(rows) - 1 or r.get("pickup_type", "") == "1":
                    continue
                hs = r.get("stop_headsign", "") or t.get("trip_headsign", "") or lastname
                deps.append((k, r, hs))

            def fmt(sec, bid):
                z = ZoneInfo(btz(bid))
                dt = datetime.fromtimestamp(origin + sec, z)
                o = dt.utcoffset()
                tot = int(o.total_seconds())
                sign = "+" if tot >= 0 else "-"
                tot = abs(tot)
                return dt.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, tot // 3600, tot % 3600 // 60)

            def emit(k, r, hs, kind, s0, s1, hw):
                bid = board_of(r["stop_id"])
                if bid not in board_stops:
                    return
                pc = stops[r["stop_id"]].get("platform_code", "") or None
                out_boards[(bid, ds)].append(({
                    "kind": kind,
                    "time": fmt(s0, bid),
                    "until": fmt(s1, bid) if kind == "interval" else None,
                    "headway_secs": hw,
                    "route": label, "headsign": hs, "trip": tid,
                    "platform": pc, "agency": aid,
                }, s0))

            if tid in freqs:
                base = times[0]
                for w in freqs[tid]:
                    a, b, h = ftime(w["start_time"]), ftime(w["end_time"]), int(w["headway_secs"])
                    if a >= b:
                        continue
                    starts = list(range(a, b, h))
                    exact = w.get("exact_times", "") == "1"
                    for k, r, hs in deps:
                        off = times[k] - base
                        if exact:
                            for s in starts:
                                emit(k, r, hs, "scheduled", s + off, None, None)
                        else:
                            emit(k, r, hs, "interval", starts[0] + off, starts[-1] + off, h)
            else:
                for k, r, hs in deps:
                    emit(k, r, hs, "scheduled", times[k], None, None)

    res = []
    for (bid, ds) in sorted(out_boards):
        # sort by instant (absolute), then keys
        lst = out_boards[(bid, ds)]
        # recompute absolute instant via time string
        def key(x):
            dep = x[0]
            inst = datetime.fromisoformat(dep["time"]).timestamp()
            return (inst, dep["route"], dep["headsign"], dep["trip"],
                    (0, "") if dep["platform"] is None else (1, dep["platform"]))
        lst.sort(key=key)
        res.append({"stop_id": bid, "name": board_stops[bid]["stop_name"], "timezone": btz(bid),
                    "service_date": ds, "departures": [x[0] for x in lst]})
    with open(outp, "w", encoding="utf-8") as f:
        json.dump({"service_dates": dates, "boards": res}, f, ensure_ascii=False)


